/****************************************************************************
 * board/beken/chips/bk7258/include/bk7258_qspi.h
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_QSPI_H
#define __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_QSPI_H

#include <stdint.h>

/* Minimal QSPI0 command-channel driver.  Supports issuing a single
 * indirect command (opcode + optional up to 4 data bytes) and polling for
 * completion.  Does not implement DMA-backed bulk transfer or the receive
 * (cmd_d) channel's multi-word read path beyond what bk7258_qspi_read_id
 * needs.
 */

void bk7258_qspi0_init(void);
bool bk7258_qspi0_send_cmd(uint8_t cmd, const uint8_t *data, uint8_t data_len);
uint32_t bk7258_qspi0_read_id(void);

#endif /* __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_QSPI_H */
/****************************************************************************
 * vendor/beken/chips/bk7258/hardware/bk7258_memorymap.h
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VENDOR_BEKEN_CHIPS_BK7258_HARDWARE_BK7258_MEMORYMAP_H
#define __VENDOR_BEKEN_CHIPS_BK7258_HARDWARE_BK7258_MEMORYMAP_H

/* Secure aliases used by the current BK7258 AP SPE image. */

#define BK7258_FLASH_BASE          0x02000000u
#define BK7258_AP_FLASH_BASE       0x02150000u
#define BK7258_AP_FLASH_SIZE       0x00110000u

#define BK7258_AP_RAM_BASE         0x28010000u
#define BK7258_AP_RAM_SIZE         0x00054000u
#define BK7258_AP_RAM_END          (BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE)

#define BK7258_SYSCTRL_BASE        0x44010000u
#define BK7258_AON_GPIO_BASE       0x44000400u
#define BK7258_UART1_BASE          0x45830000u
#define BK7258_MBOX0_BASE          0x41000000u
#define BK7258_QSPI0_BASE          0x46040000u

/* Hardware I2C1 controller (SOC_I2C1_REG_BASE,
 * bk_avdk_smp/ap/include/soc/bk7258/reg_base.h:92).  Used for GC2145
 * register access on this board: per the board schematic
 * (AIDK_AI玩具开发板_原理图.pdf sheet 4/6 "DVP/SENSOR/NAND/MOTOR/KEY"),
 * GC2145's SCL/SDA are wired to IIC1_SCL/IIC1_SDA (with 4.7K pull-ups to
 * VDDGPIO), which the chip's GPIO pinmux table
 * (bk_avdk_smp/ap/middleware/soc/bk7258_ap/soc/gpio_map.h
 * GPIO_I2C1_MAP_TABLE) routes to GPIO42/GPIO43 (the second of two
 * selectable I2C1 pin groups; the other group, GPIO0/GPIO1, is what this
 * driver's previous software-simulated-I2C implementation incorrectly
 * assumed and is actually wired to UART1_TXD/UART1_RXD on this board --
 * see bk7258_i2c1.c file header for the full corrected-vs-original
 * comparison). */
#define BK7258_I2C1_BASE           0x45860000u

/* PSRAM data region.  YUV_BUF hardware uses a fixed base address here
 * (SOC_PSRAM_DATA_BASE, ap/include/soc/bk7258/reg_base.h:43) as its line
 * buffer in YUV direct-capture mode (yuv_buf_hal_set_yuv_mode_config()
 * hard-codes em_base_addr/emr_base_addr to this address, not an
 * application-supplied one).  Size: the actual PSRAM chip on this board
 * has been observed at boot to be 16MB (serial log:
 * "psram type(16MB) not match CONFIG_PSRAM_CAPACITY 0X00800000"), so
 * 0x01000000 (16MB) is used here rather than the chip-family maximum
 * SOC_PSRAM_DATA_SIZE (0x4000000, 64MB) -- both are valid MPU region
 * sizes (power-of-two, naturally aligned to SOC_PSRAM_DATA_BASE), 16MB
 * matches the verified real hardware capacity.
 */
#define BK7258_PSRAM_BASE          0x60000000u
#define BK7258_PSRAM_SIZE          0x01000000u

#define BK7258_NVIC_BASE           0xe000e100u
#define BK7258_SCB_BASE            0xe000ed00u
#define BK7258_SAU_BASE            0xe000edd0u

#endif
/****************************************************************************
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

#include <nuttx/irq.h>
#include <nuttx/spinlock.h>

#include "arm_internal.h"
#include "hardware/bk7258_gpio.h"

void bk7258_gpio_input_pullup(unsigned int pin)
{
  irqstate_t flags;

  flags = enter_critical_section();
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_OUTPUT | BK7258_GPIO_SECOND_FUNCTION,
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT_DISABLE |
              BK7258_GPIO_PULL_UP | BK7258_GPIO_PULL_ENABLE);
  leave_critical_section(flags);
}

void bk7258_gpio_output(unsigned int pin, bool value)
{
  irqstate_t flags;
  uint32_t setbits = value ? BK7258_GPIO_OUTPUT : 0;

  flags = enter_critical_section();
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT |
              BK7258_GPIO_OUTPUT_DISABLE | BK7258_GPIO_PULL_ENABLE |
              BK7258_GPIO_SECOND_FUNCTION,
              setbits);
  leave_critical_section(flags);
}

void bk7258_gpio_write(unsigned int pin, bool value)
{
  if (value)
    {
      modifyreg32(BK7258_GPIO_CFG(pin), 0, BK7258_GPIO_OUTPUT);
    }
  else
    {
      modifyreg32(BK7258_GPIO_CFG(pin), BK7258_GPIO_OUTPUT, 0);
    }
}

bool bk7258_gpio_read(unsigned int pin)
{
  return (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_INPUT) != 0;
}

void bk7258_gpio_set_function(unsigned int pin, unsigned int function)
{
  irqstate_t flags;
  uintptr_t regaddr = BK7258_GPIO_SYS_CFG(pin);
  uint32_t shift = BK7258_GPIO_SYS_SHIFT(pin);

  flags = enter_critical_section();
  modifyreg32(regaddr, BK7258_GPIO_SYS_MASK(pin), (function & 0xfu) << shift);
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT |
              BK7258_GPIO_PULL_ENABLE,
              BK7258_GPIO_OUTPUT_DISABLE | BK7258_GPIO_SECOND_FUNCTION);
  leave_critical_section(flags);
}
/****************************************************************************
 * board/beken/chips/bk7258/include/bk7258_gpio.h
 *
 * Function prototypes for bk7258_gpio.c (general-purpose GPIO driver).
 * Register-level macros (BK7258_GPIO_CFG etc.) live in the separate
 * hardware/bk7258_gpio.h; this header only declares the functions that
 * operate on those registers, so callers outside bk7258_gpio.c do not
 * need to hand-write extern declarations (as bk7258_pwm.c previously did
 * for bk7258_gpio_set_function()).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_GPIO_H
#define __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_GPIO_H

#include <stdbool.h>

void bk7258_gpio_input_pullup(unsigned int pin);
void bk7258_gpio_output(unsigned int pin, bool value);
void bk7258_gpio_write(unsigned int pin, bool value);
bool bk7258_gpio_read(unsigned int pin);
void bk7258_gpio_set_function(unsigned int pin, unsigned int function);

#endif /* __VENDOR_BEKEN_CHIPS_BK7258_INCLUDE_BK7258_GPIO_H */

