	// set gpio as second function mode
	gpio_hal_output_enable(hal, gpio_id, 0);
	gpio_hal_input_enable(hal, gpio_id, 0);
	gpio_hal_pull_enable(hal, gpio_id, 0);
	gpio_hal_sencond_function_enable(hal, gpio_id, 1);

	return BK_OK;
}

