void bk7258_gpio_set_function(unsigned int pin, unsigned int function)
{
  irqstate_t flags;
  uintptr_t regaddr = BK7258_GPIO_SYS_CFG(pin);
  uint32_t shift = BK7258_GPIO_SYS_SHIFT(pin);

  flags = enter_critical_section();
  modifyreg32(regaddr, BK7258_GPIO_SYS_MASK(pin), (function & 0xfu) << shift);

  /* Per gpio_hal_func_map()'s reference call sequence (output_enable=0,
   * input_enable=0, pull_enable=0, then second_function_enable=1):
   * relinquish the plain-GPIO input/output/pull drivers on this pad so
   * the peripheral controller's own signal fully takes over, then
   * enable second-function routing.  Corrected from this function's
   * original (inverted) bit usage, which cleared BK7258_GPIO_OUTPUT (a
   * pure output-*level* bit, not a driver-enable bit -- clearing it did
   * nothing useful here) and *set* what was then mis-named
   * BK7258_GPIO_OUTPUT_DISABLE (bit[3], real meaning output_en) -- i.e.
   * every peripheral pinmux call (QSPI1's 4 shared pads, I2C1's 2 shared
   * pads) was leaving the plain-GPIO output driver enabled and fighting
   * the peripheral controller for control of the pad, instead of being
   * disabled as gpio_hal_output_enable(hal, gpio_id, 0) does in the
   * reference driver.  See hardware/bk7258_gpio.h's
   * BK7258_GPIO_OUTPUT_ENABLE comment for the full diagnostic trail this
   * was found through. */
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT_ENABLE |
              BK7258_GPIO_PULL_ENABLE,
              BK7258_GPIO_SECOND_FUNCTION);
  leave_critical_section(flags);
}

