void bk7258_gpio_input_pullup(unsigned int pin)
{
  irqstate_t flags;

  flags = enter_critical_section();

  /* Per gpio_struct.h's authoritative bitfield layout (see
   * hardware/bk7258_gpio.h's BK7258_GPIO_OUTPUT_ENABLE comment for the
   * full citation): input mode wants input_en=1, output_en=0,
   * pull_up=1, pull_en=1, second_func_en=0.  Corrected from this
   * function's original (inverted) bit usage, which cleared
   * BK7258_GPIO_OUTPUT (a no-op here since output_en was never set by
   * this path) and set what was then mis-named
   * BK7258_GPIO_OUTPUT_DISABLE (bit[3], real meaning output_en) --
   * i.e. it was turning output_en *on* instead of off. */
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_OUTPUT | BK7258_GPIO_OUTPUT_ENABLE |
              BK7258_GPIO_SECOND_FUNCTION,
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_PULL_UP |
              BK7258_GPIO_PULL_ENABLE);
  leave_critical_section(flags);
}

void bk7258_gpio_output(unsigned int pin, bool value)
{
  irqstate_t flags;
  uint32_t setbits = BK7258_GPIO_OUTPUT_ENABLE;

  if (value)
    {
      setbits |= BK7258_GPIO_OUTPUT;
    }

  flags = enter_critical_section();

  /* Per gpio_struct.h: output mode wants output_en=1 (the pin's output
   * driver actually enabled) plus the desired output-level bit,
   * input_en=0, pull_en=0, second_func_en=0.  Corrected from this
   * function's original (inverted) bit usage, which set the desired
   * output level correctly but then *cleared* what was then mis-named
   * BK7258_GPIO_OUTPUT_DISABLE (bit[3], real meaning output_en) -- i.e.
   * it was turning the pin's output driver *off* right after setting
   * its level, so every caller of this function (GC2145's power/reset
   * GPIOs, GC9D01's reset GPIO) was never actually driving its pin.
   * See hardware/bk7258_gpio.h's BK7258_GPIO_OUTPUT_ENABLE comment for
   * the full diagnostic trail this was found through. */
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT |
              BK7258_GPIO_OUTPUT_ENABLE | BK7258_GPIO_PULL_ENABLE |
              BK7258_GPIO_SECOND_FUNCTION,
              setbits);
  leave_critical_section(flags);
}

